1	@import "tailwindcss";
2	
3	@theme {
4	  --color-brand-50: #f2f0ff;
5	  --color-brand-100: #e4e0ff;
6	  --color-brand-200: #c9c2ff;
7	  --color-brand-300: #a89aff;
8	  --color-brand-400: #8a70fb;
9	  --color-brand-500: #6f47f5;
10	  --color-brand-600: #5f2ee8;
11	  --color-brand-700: #5124c4;
12	  --color-brand-800: #421fa0;
13	  --color-brand-900: #371d7f;
14	
15	  --color-navy-950: #060a14;
16	  --color-navy-900: #0a101f;
17	  --color-navy-850: #0d1526;
18	  --color-navy-800: #111a30;
19	  --color-navy-700: #1a2540;
20	  --color-navy-600: #253354;
21	
22	  --color-accent-blue: #3b82f6;
23	  --color-accent-cyan: #22d3ee;
24	
25	  --animate-fade-up: fade-up 0.4s ease-out both;
26	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
27	
28	  /* Showcase mock-screen animations (marketing product pages). All are opt-in
29	     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
30	     resting state (bars full, lines visible) with no motion. */
31	  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
32	  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
33	  --animate-eq: eq 1.7s ease-in-out infinite;
34	  --animate-blink: blink 1.1s steps(1) infinite;
35	  --animate-sweep: sweep 3.4s ease-in-out infinite;
36	  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
37	
38	  @keyframes fade-up {
39	    from { opacity: 0; transform: translateY(8px); }
40	    to { opacity: 1; transform: translateY(0); }
41	  }
42	  @keyframes pulse-dot {
43	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
44	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
45	  }
46	  /* One-shot bar grow (origin at the base). Resting state = full. */
47	  @keyframes grow-up {
48	    from { transform: scaleY(0.06); }
49	    to { transform: scaleY(1); }
50	  }
51	  /* One-shot progress/usage fill. Resting state = full width. */
52	  @keyframes grow-x {
53	    from { transform: scaleX(0); }
54	    to { transform: scaleX(1); }
55	  }
56	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
57	  @keyframes eq {
58	    0%, 100% { transform: scaleY(0.35); }
59	    50% { transform: scaleY(1); }
60	  }
61	  /* Terminal cursor blink. Resting state = visible. */
62	  @keyframes blink {
63	    0%, 49% { opacity: 1; }
64	    50%, 100% { opacity: 0; }
65	  }
66	  /* Soft light sweep across a chart/highlight. */
67	  @keyframes sweep {
68	    0% { transform: translateX(-120%); opacity: 0; }
69	    40%, 60% { opacity: 0.7; }
70	    100% { transform: translateX(320%); opacity: 0; }
71	  }
72	  /* Staggered line/row reveal. Resting state = visible. */
73	  @keyframes line-in {
74	    from { opacity: 0; transform: translateY(6px); }
75	    to { opacity: 1; transform: translateY(0); }
76	  }
77	}
78	
79	body {
80	  @apply bg-navy-950 text-slate-100 antialiased;
81	  background-image:
82	    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
83	    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
84	  background-attachment: fixed;
85	}
86	
87	::-webkit-scrollbar { width: 10px; height: 10px; }
88	::-webkit-scrollbar-track { background: transparent; }
89	::-webkit-scrollbar-thumb { background: #253354; border-radius: 8px; border: 2px solid #060a14; }
90	::-webkit-scrollbar-thumb:hover { background: #34456e; }
91	
92	@layer components {
93	  /* Surfaces */
94	  .card {
95	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
96	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
97	  }
98	  .card-hover {
99	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
100	  }
101	  .glass {
102	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
103	  }
104	  .glow-brand {
105	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
106	  }
107	
108	  /* Typography */
109	  .grad-text {
110	    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
111	  }
112	  .page-title {
113	    @apply text-2xl font-bold tracking-tight;
114	  }
115	  .section-label {
116	    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
117	  }
118	
119	  /* Buttons */
120	  .btn-primary,
121	  .btn-secondary,
122	  .btn-danger,
123	  .btn-ghost {
124	    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
125	  }
126	  .btn-primary {
127	    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
128	    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
129	  }
130	  .btn-secondary {
131	    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
132	  }
133	  .btn-danger {
134	    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
135	  }
136	  .btn-ghost {
137	    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
138	  }
139	
140	  /* Forms */
141	  .input {
142	    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
143	  }
144	  .label {
145	    @apply mb-1.5 block text-xs font-medium uppercase tracking-wide text-slate-400;
146	  }
147	
148	  /* Nav */
149	  .nav-item {
150	    @apply flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white;
151	  }
152	  .nav-item-active {
153	    @apply bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white;
154	    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
155	  }
156	
157	  /* Tables */
158	  .table-shell {
159	    @apply w-full text-sm;
160	  }
161	  .table-shell thead th {
162	    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
163	  }
164	  .table-shell tbody tr {
165	    @apply border-t border-white/[0.05] transition-colors hover:bg-white/[0.02];
166	  }
167	  .table-shell tbody td {
168	    @apply px-4 py-3;
169	  }
170	
171	  /* Misc */
172	  .kbd {
173	    @apply rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[11px] text-slate-400;
174	  }
175	  .divider {
176	    @apply my-4 border-t border-white/[0.06];
177	  }
178	  .skeleton {
179	    @apply animate-pulse rounded-lg bg-white/[0.06];
180	  }
181	
182	  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
183	     Shared primitives so every page reads as one designed site. The Section
184	     component alternates these background "tones" to give the long pages rhythm
185	     instead of a flat stack. Colors/animations are the existing brand system. */
186	
187	  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
188	  .eyebrow {
189	    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
190	  }
191	  .eyebrow-pill {
192	    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
193	  }
194	
195	  /* Section background tones for alternating rhythm. "panel" is a hair lighter
196	     than the page with hairline separators; "deep" recedes. Replaces one-off
197	     inline gradients scattered across pages. */
198	  .tone-panel {
199	    @apply border-y border-white/[0.05] bg-navy-900/40;
200	  }
201	  .tone-deep {
202	    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
203	  }
204	
205	  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
206	     text automatically. Default = the dark theme's light text. */
207	  :root {
208	    --fg: #ffffff;
209	    --fg-muted: #94a3b8; /* slate-400 */
210	  }
211	
212	  /* "light" tone — a rare, deliberate light band to break up the dark theme and
213	     divide long pages (used sparingly, ~one per page). Flips the foreground
214	     tokens to dark and restyles surfaces/buttons inside so everything stays
215	     legible without touching each call site. */
216	  .tone-light {
217	    @apply border-y border-slate-200/70 text-slate-700;
218	    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
219	    --fg: #0f172a;       /* slate-900 */
220	    --fg-muted: #475569; /* slate-600 */
221	  }
222	  .tone-light .card {
223	    @apply border-slate-200 bg-white text-slate-700;
224	    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
225	  }
226	  .tone-light .card-hover:hover {
227	    @apply border-brand-500/40 bg-white;
228	  }
229	  .tone-light .glass {
230	    @apply border-slate-200 bg-white/70;
231	  }
232	  .tone-light .section-label {
233	    @apply text-slate-500;
234	  }
235	  .tone-light .btn-secondary {
236	    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
237	  }
238	  .tone-light .btn-ghost {
239	    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
240	  }
241	
242	  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
243	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
244	  .hero-aura {
245	    background-image:
246	      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
247	      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
248	  }
249	
250	  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
251	  .lift {
252	    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
253	    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
254	  }
255	
256	  /* Consistent max-width content rail. */
257	  .rail {
258	    @apply mx-auto max-w-6xl px-5 sm:px-6;
259	  }
260	
261	  /* Top-nav dropdown trigger button. */
262	  .nav-trigger {
263	    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
264	  }
265	  .nav-trigger.is-open {
266	    @apply text-white;
267	  }
268	
269	  /* Animated gradient underline that wipes in on hover (rocket-style nav). Sits
270	     inside the px-3 padding so it tracks the label width. */
271	  .nav-underline {
272	    position: relative;
273	  }
274	  .nav-underline::after {
275	    content: "";
276	    position: absolute;
277	    left: 12px;
278	    right: 12px;
279	    bottom: 5px;
280	    height: 1.5px;
281	    border-radius: 2px;
282	    background: linear-gradient(90deg, var(--color-accent-blue), var(--color-brand-400));
283	    transform: scaleX(0);
284	    transform-origin: left center;
285	    transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
286	  }
287	  .nav-underline:hover::after,
288	  .nav-underline:focus-visible::after,
289	  .nav-underline.is-open::after {
290	    transform: scaleX(1);
291	  }
292	  @media (prefers-reduced-motion: reduce) {
293	    .nav-underline::after { transition: none; }
294	  }
295	}
