import Link from "next/link";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";

/**
 * Third-party review badges (Trustpilot · HostAdvice · Google) for the hero.
 *
 * REAL DATA, WITH AN HONEST FALLBACK (2026-08-10). This component now reads the
 * live Reviews engine:
 *
 *   - It aggregates APPROVED reviews by external source (Google/Trustpilot/
 *     HostAdvice) into a real average score and count, and links each badge to
 *     the review-profile URL configured in /admin/reviews.
 *   - A source is only shown as a REAL badge when it has ≥1 approved review AND a
 *     configured profile URL — so we never render a live-looking badge that links
 *     nowhere or is backed by nothing.
 *   - When NO source qualifies (the normal pre-launch state), it falls back to the
 *     clearly-labelled DEMO PLACEHOLDER below, so the hero never looks empty.
 *
 * ⚠️ DEMO PLACEHOLDER — the scores/counts in `DEMO_BADGES` are NOT real review
 * data. They exist only so the hero has something to show before real reviews are
 * approved. They are never mixed with real data: the moment one real external
 * review exists, the whole strip switches to real badges only. Do not publish
 * these figures as genuine — collect real reviews (they'll appear automatically).
 */

type Badge = { name: string; score: string; count: string; href: string; star: string; google?: boolean };

const DEMO_BADGES: Badge[] = [
  { name: "Trustpilot", score: "4.9", count: "312", href: "#", star: "#00b67a" },
  { name: "HostAdvice", score: "4.8", count: "148", href: "#", star: "#f5a623" },
  { name: "Google", score: "4.9", count: "205", href: "#", star: "#fbbc05", google: true },
];

const SOURCE_META: Record<string, { name: string; star: string; google?: boolean; urlKey: string }> = {
  TRUSTPILOT: { name: "Trustpilot", star: "#00b67a", urlKey: "review_url_trustpilot" },
  HOSTADVICE: { name: "HostAdvice", star: "#f5a623", urlKey: "review_url_hostadvice" },
  GOOGLE: { name: "Google", star: "#fbbc05", google: true, urlKey: "review_url_google" },
};

function Stars({ color }: { color: string }) {
  return (
    <span style={{ color }} className="text-[13px] leading-none tracking-tight" aria-hidden>
      ★★★★★
    </span>
  );
}

/** Aggregate approved external reviews into real badges; empty when none qualify. */
async function realBadges(): Promise<Badge[]> {
  try {
    const [grouped, trustpilot, hostadvice, google] = await Promise.all([
      db.review.groupBy({
        by: ["source"],
        where: { approved: true, source: { in: ["TRUSTPILOT", "HOSTADVICE", "GOOGLE"] } },
        _avg: { rating: true },
        _count: { _all: true },
      }),
      getSetting("review_url_trustpilot"),
      getSetting("review_url_hostadvice"),
      getSetting("review_url_google"),
    ]);
    const urls: Record<string, string> = {
      review_url_trustpilot: trustpilot,
      review_url_hostadvice: hostadvice,
      review_url_google: google,
    };

    const out: Badge[] = [];
    for (const g of grouped) {
      const meta = SOURCE_META[g.source];
      const count = g._count._all;
      const avg = g._avg.rating ?? 0;
      const url = meta ? (urls[meta.urlKey] ?? "").trim() : "";
      if (!meta || count < 1 || !url) continue; // real data AND somewhere to link
      out.push({
        name: meta.name,
        score: avg.toFixed(1),
        count: String(count),
        href: url,
        star: meta.star,
        google: meta.google,
      });
    }
    return out;
  } catch {
    return [];
  }
}

export async function ReviewBadges() {
  const real = await realBadges();
  const badges = real.length > 0 ? real : DEMO_BADGES;
  const external = real.length > 0;

  return (
    <div className="flex flex-wrap items-center gap-x-4 gap-y-3">
      {badges.map((b) => (
        <Link
          key={b.name}
          href={b.href}
          {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
          className="group flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.03] px-3 py-1.5 transition-colors hover:border-white/15"
          aria-label={`${b.score} out of 5 on ${b.name} — ${b.count} reviews`}
        >
          <Stars color={b.star} />
          <span className="text-xs text-slate-400">
            <span className="font-semibold text-white">{b.score}</span> on{" "}
            {b.google ? (
              <span className="font-semibold">
                <span style={{ color: "#4285F4" }}>G</span><span style={{ color: "#EA4335" }}>o</span><span style={{ color: "#FBBC05" }}>o</span><span style={{ color: "#4285F4" }}>g</span><span style={{ color: "#34A853" }}>l</span><span style={{ color: "#EA4335" }}>e</span>
              </span>
            ) : (
              <span className="font-semibold text-slate-300">{b.name}</span>
            )}{" "}
            <span className="text-slate-500">({b.count})</span>
          </span>
        </Link>
      ))}
    </div>
  );
}
