import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconArrow, IconBolt } from "./icons";

/**
 * The persuasion centerpiece of /pricing — the four-term commitment ladder,
 * worked on the entry VPS. Presentational only: it renders NOTHING it isn't
 * handed. Every number arrives pre-formatted from the server page, where it was
 * derived from the live catalogue price through `termPriceCents` + the admin
 * annual rate (the SAME formula checkout charges and renewals bill) — so this
 * component can never advertise a figure the checkout won't honour, and there is
 * not one hard-coded price in here.
 *
 * Brand system only: navy glass, violet brand, cyan = the "best value" pop
 * (never amber). Longer term ⇒ lower $/mo, and each rung says by exactly how much.
 */
export type TermRung = {
  label: string;
  short: string;
  /** effective $/mo after the term discount, pre-formatted */
  perMoLabel: string;
  /** undiscounted monthly, pre-formatted (strike-through) */
  monthlyLabel: string;
  /** total billed up front for the whole term, pre-formatted */
  totalLabel: string;
  /** "monthly" | "every 2 yr" … */
  cadenceLabel: string;
  /** "Save $X over 2 yr" | "Flexible — cancel anytime" */
  savingsLabel: string;
  /** real term discount %, 0 for monthly */
  discountPct: number;
  hasSavings: boolean;
  recommended: boolean;
  bestValue: boolean;
};

export function TermLadder({
  planName,
  planMonthlyLabel,
  maxDiscountPct,
  bestSavingsLabel,
  rungs,
}: {
  planName: string;
  planMonthlyLabel: string;
  maxDiscountPct: number;
  bestSavingsLabel: string;
  rungs: TermRung[];
}) {
  return (
    <div className="grid gap-10 lg:grid-cols-[0.82fr_1.18fr] lg:items-center">
      {/* Editorial rail */}
      <Reveal>
        <span className="eyebrow"><IconBolt size={14} /> The commitment ladder</span>
        <h2 className="mt-4 text-4xl font-bold leading-[1.03] tracking-tight text-white sm:text-5xl text-balance">
          Commit longer.<br />Pay <span className="grad-text">a lot less.</span>
        </h2>
        {maxDiscountPct > 0 && (
          <p className="mt-6 flex items-baseline gap-3">
            <span className="text-6xl font-black tabular-nums text-accent-cyan sm:text-7xl" style={{ textShadow: "0 0 42px rgba(34,211,238,0.35)" }}>
              −{maxDiscountPct}%
            </span>
            <span className="text-sm leading-tight text-slate-400">
              off the monthly rate
              <br />on the longest term
            </span>
          </p>
        )}
        <p className="mt-6 max-w-sm text-[15px] leading-relaxed text-slate-400">
          Worked on the <span className="font-semibold text-slate-200">{planName}</span> at{" "}
          <span className="font-semibold text-slate-200">{planMonthlyLabel}/mo</span> — every VPS plan
          scales down the same way. {bestSavingsLabel}
        </p>
        <div className="mt-6 space-y-2.5 text-sm text-slate-300">
          {[
            "The price you sign up at is the price you renew at",
            "No lock-in — cancel anytime, billing stops at term end",
            "Pay once, up front, from your wallet or by card",
          ].map((t) => (
            <p key={t} className="flex items-start gap-2.5">
              <span className="mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-accent-cyan/15 text-accent-cyan">✓</span>
              {t}
            </p>
          ))}
        </div>
        <Link href="/register" className="btn-primary mt-8 px-5 py-3 text-base">
          Pick your term in the deploy wizard <IconArrow size={16} />
        </Link>
      </Reveal>

      {/* The four rungs — ascending emphasis, longest = the cyan hero card */}
      <Reveal delay={120}>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {rungs.map((r, i) => {
            const hero = r.bestValue;
            return (
              <div
                key={r.label}
                className={`relative flex flex-col rounded-2xl border p-5 transition-transform duration-200 hover:-translate-y-1 ${
                  hero
                    ? "border-accent-cyan/40 bg-gradient-to-b from-accent-cyan/[0.10] to-brand-500/[0.06] xl:-translate-y-3 xl:scale-[1.03]"
                    : r.recommended
                      ? "border-brand-500/35 bg-brand-500/[0.05]"
                      : "border-white/[0.07] bg-navy-900/60"
                }`}
                style={hero ? { boxShadow: "0 0 44px -12px rgba(34,211,238,0.4)" } : undefined}
              >
                {(r.bestValue || r.recommended) && (
                  <span
                    className={`absolute -top-2.5 left-5 rounded-full px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider text-white shadow ${
                      r.bestValue
                        ? "bg-gradient-to-r from-accent-cyan to-accent-blue text-navy-950"
                        : "bg-gradient-to-r from-accent-blue to-brand-500"
                    }`}
                  >
                    {r.bestValue ? "Best value" : "Recommended"}
                  </span>
                )}
                <div className="flex items-center justify-between gap-2">
                  <span className="text-sm font-semibold text-white">{r.label}</span>
                  {r.discountPct > 0 && (
                    <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${hero ? "bg-accent-cyan/20 text-accent-cyan" : "bg-emerald-500/15 text-emerald-300"}`}>
                      −{r.discountPct}%
                    </span>
                  )}
                </div>
                <p className="mt-3 flex items-baseline gap-1.5">
                  <span className={`text-3xl font-black tabular-nums ${hero ? "text-accent-cyan" : "text-white"}`}>{r.perMoLabel}</span>
                  <span className="text-xs text-slate-400">/mo</span>
                </p>
                {r.discountPct > 0 && (
                  <p className="mt-0.5 text-[11px] text-slate-500">
                    <span className="line-through tabular-nums">{r.monthlyLabel}</span> monthly
                  </p>
                )}
                <div className="my-3 h-px bg-white/[0.06]" />
                <p className="text-[11px] leading-relaxed text-slate-500">
                  {r.totalLabel} billed {r.cadenceLabel}
                </p>
                <p className={`mt-1.5 text-[11px] font-semibold ${r.hasSavings ? (hero ? "text-accent-cyan" : "text-emerald-300") : "text-slate-500"}`}>
                  {r.savingsLabel}
                </p>
                {/* subtle ascending fill so the eye reads left→right = more saved */}
                <div className="mt-4 h-1 w-full overflow-hidden rounded-full bg-white/[0.06]">
                  <div
                    className={`h-full rounded-full ${hero ? "bg-gradient-to-r from-accent-blue to-accent-cyan" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
                    style={{ width: `${25 + i * 25}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
        <p className="mt-4 text-xs text-slate-500">
          Effective monthly equivalents — the whole term is billed once, up front. Multi-year terms
          (Biennial · Triennial) are VPS-only; Shared Hosting &amp; Business Email offer Monthly and Annual.
        </p>
      </Reveal>
    </div>
  );
}

