/**
 * The ONE money helper for this page. Every price rendered below is passed
 * through here straight from a database record (db.plan / db.hostingPlan /
 * db.emailPlan / db.gamePlan) — there is not a single hard-coded plan price on
 * this page, so a catalogue edit propagates here automatically and can never
 * advertise a number checkout won't honour. (Domain TLDs are the one exception
 * and are explicitly labelled "indicative" — there is no TLD price table to read
 * and the domain search quotes the live, exact figure.)
 */
function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}
function gb(mb: number): string {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}

