export default async function PricingPage() {
  // Every product line's prices — read live from the catalogue. Nothing below is
  // hard-coded; if a plan is edited or deactivated in the DB, this page follows.
  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
  ]);

  // Group game plans by family, in canonical order, keeping only families that
  // actually have a real per-game plan (honesty: no per-game price is claimed
  // over a title that lacks one — those deploy on a plain VPS instead).
  const byGame = new Map<string, typeof gamePlans>();
  for (const g of gamePlans) {
    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
    byGame.get(g.gameFamily)!.push(g);
  }
  const games = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0);
  const GAME_META: Record<string, { name: string; tag: string }> = {
    minecraft: { name: "Minecraft", tag: "Java & Bedrock" },
    valheim: { name: "Valheim", tag: "Dedicated world" },
    rust: { name: "Rust", tag: "High player counts" },
    palworld: { name: "Palworld", tag: "Co-op survival" },
    cs2: { name: "Counter-Strike 2", tag: "Competitive FPS" },
    terraria: { name: "Terraria", tag: "Sandbox worlds" },
  };

  // Promo copy comes from the single source of truth. It is shown ONLY where the
  // owner scoped it — shared web hosting — via firstMonthFreeAppliesTo("HOSTING").
  const promo = currentPromo(new Date());
  const hostingHasPromo = firstMonthFreeAppliesTo("HOSTING");

  // The REAL annual discount, read from the admin setting (lib/annual-discount.ts) —
  // never a hardcoded marketing number. The annual term genuinely exists in the
  // deploy wizard and is charged/renewed at this rate (lib/order.ts, renewalCharge),
  // so surfacing it here is honest. Only shown when it is actually a discount.
  const annualPct = await annualDiscountPct();

  const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;

  // Cheapest plan per product line, for the "index" overview — every figure below
  // is the same DB record the section deep-dives read, so the summary and the
  // detail can never disagree.
  const cheapest = <T extends { priceCents: number }>(arr: T[]): T | null =>
    arr.length ? arr.reduce((a, b) => (b.priceCents < a.priceCents ? b : a)) : null;
  const planFrom = (p: { priceCents: number; termMonths?: number } | null): string =>
    p ? `${money(p.priceCents)}${p.termMonths && p.termMonths > 1 ? ` / ${p.termMonths} mo` : "/mo"}` : "—";
  const vpsMin = cheapest(vpsPlans);
  const gameMin = cheapest(gamePlans);
  const hostingMin = cheapest(hostingPlans);
  const emailMin = cheapest(emailPlans);
  const domainMin = POPULAR_TLDS.length ? Math.min(...POPULAR_TLDS.map((t) => t.fromCents)) : null;

  // The product index (chooser + at-a-glance, merged). `from` is always DB-derived
  // (domains are the labelled "indicative" exception, matching the domains section).
  const INDEX: { icon: ReactNode; name: string; who: string; from: string; billing: string; href: string; accent: string }[] = [
    { icon: <IconTerminal />, name: "Cloud VPS", who: "Full root, any stack, resize on demand", from: planFrom(vpsMin), billing: "Monthly · resize anytime", href: "#vps", accent: "brand-300" },
    { icon: <IconGame />, name: "Game Servers", who: "Low-latency worlds, one-click deploy", from: gameMin ? `from ${planFrom(gameMin)}` : "—", billing: "Per game · monthly", href: "#game-servers", accent: "emerald-300" },
    { icon: <IconApps />, name: "Shared Hosting", who: "WordPress & SSL, no server to manage", from: planFrom(hostingMin), billing: hostingHasPromo ? "First month free · then monthly" : "Monthly · no lock-in", href: "#hosting", accent: "accent-cyan" },
    { icon: <IconMail />, name: "Business Email", who: "Mailboxes at your own domain", from: planFrom(emailMin), billing: "Monthly", href: "#email", accent: "sky-300" },
    { icon: <IconGlobe />, name: "Domains", who: "Register, manage DNS, point at your VPS", from: domainMin != null ? `from ${money(domainMin)}/yr*` : "—", billing: "Yearly registration", href: "#domains", accent: "brand-300" },
  ];

  // The commitment ladder, worked on the entry VPS. Every figure runs the live
  // catalogue price through termPriceCents (the SAME formula checkout charges &
  // renewals bill) with the live admin annual rate — zero hard-coded prices.
  const longestMonths = VPS_TERMS[VPS_TERMS.length - 1].months;
  let ladderRungs: TermRung[] = [];
  let maxDiscountPct = 0;
  let bestSavingsLabel = "";
  if (vpsMin) {
    ladderRungs = VPS_TERMS.map((t) => {
      const total = termPriceCents(vpsMin.priceCents, t.months, annualPct);
      const perMo = Math.round(total / t.months);
      const savings = vpsMin.priceCents * t.months - total;
      const disc = t.months === ANNUAL_TERM_MONTHS ? annualPct : t.discountPct;
      const isLongest = t.months === longestMonths;
      return {
        label: t.label,
        short: t.short,
        perMoLabel: money(perMo),
        monthlyLabel: money(vpsMin.priceCents),
        totalLabel: money(total),
        cadenceLabel: t.months === 1 ? "monthly" : `every ${t.short}`,
        savingsLabel:
          savings > 0
            ? t.months === ANNUAL_TERM_MONTHS
              ? `Save ${money(savings)}/yr`
              : `Save ${money(savings)} over ${t.short}`
            : "Flexible — cancel anytime",
        discountPct: disc,
        hasSavings: savings > 0,
        recommended: t.months === ANNUAL_TERM_MONTHS,
        bestValue: isLongest && disc > 0,
      };
    });
    const longest = VPS_TERMS[VPS_TERMS.length - 1];
    maxDiscountPct = longest.discountPct;
    const longestSavings = vpsMin.priceCents * longest.months - termPriceCents(vpsMin.priceCents, longest.months, annualPct);
    bestSavingsLabel = longestSavings > 0 ? `That's ${money(longestSavings)} back in your pocket over ${longest.short}.` : "";
  }

  return (
    <>
      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
      <FaqJsonLd items={FAQ} />

      <div className="relative overflow-hidden">
        {/* Ambient dot-field — the v5 signature the owner likes — behind the whole page. */}
        <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
          <AmbientField />
          <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_45%_at_15%_-5%,rgba(111,71,245,0.16),transparent_60%),radial-gradient(ellipse_55%_40%_at_92%_0%,rgba(59,130,246,0.12),transparent_60%)]" />
        </div>

        <div className="relative z-10">
          {/* ═══════════ HERO — asymmetric, speed-led ═══════════ */}
          <section className="rail grid items-center gap-12 py-16 lg:grid-cols-[1.08fr_0.92fr] lg:py-24">
            <Reveal>
              <span className="eyebrow-pill mb-6">
                <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Pricing · every product, one wallet
              </span>
              <h1 className="text-[3.1rem] font-black leading-[0.92] tracking-tight text-white sm:text-[4.4rem]">
                Your server is<br />
                <span className="grad-text">47 seconds away.</span>
              </h1>
              <p className="mt-6 max-w-lg text-lg leading-relaxed text-slate-400">
                Cloud VPS, game servers, shared hosting, business email and domains — every price on this
                page is read live from checkout, billed from one wallet, with no lock-in.
              </p>
              <div className="mt-7 flex flex-wrap items-center gap-3">
                <Link href="/register" className="btn-primary px-6 py-3 text-base">Create your account →</Link>
                <Link href="#index" className="btn-secondary px-6 py-3 text-base">Find my product</Link>
                {vpsFrom != null && (
                  <span className="inline-flex items-baseline gap-1.5 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5 text-sm">
                    <span className="text-slate-400">VPS from</span>
                    <span className="font-bold text-white">{money(vpsFrom)}</span>
                    <span className="text-slate-500">/mo</span>
                  </span>
                )}
              </div>
              <p className="mt-5 flex flex-wrap gap-x-5 gap-y-2 text-xs text-slate-400">
                {["The price you sign up at is the price you renew at", "No lock-in — cancel anytime", "Free migration in"].map((t) => (
                  <span key={t} className="flex items-center gap-1.5"><span className="text-accent-cyan">✓</span>{t}</span>
                ))}
              </p>
              <div className="mt-7"><ReviewBadges /></div>
            </Reveal>
            <Reveal delay={140}>
              <div className="lg:pl-4"><DeployCard /></div>
            </Reveal>
          </section>

          {/* ═══════════ MARQUEE — rhythm break ═══════════ */}
          <section className="tone-panel py-10">
            <div className="rail">
              <p className="text-center text-sm font-semibold uppercase tracking-[0.16em] text-slate-500">Deploy with any OS, panel or stack</p>
            </div>
            <div className="mt-7"><LogoMarquee /></div>
          </section>

          {/* ═══════════ COMMITMENT LADDER — the persuasion centerpiece ═══════════ */}
          {vpsMin && (
            <section className="relative py-24 sm:py-28">
              <div className="pointer-events-none absolute inset-0 -z-10 hero-aura opacity-70" aria-hidden />
              <div className="rail">
                <TermLadder
                  planName={vpsMin.name}
                  planMonthlyLabel={money(vpsMin.priceCents)}
                  maxDiscountPct={maxDiscountPct}
                  bestSavingsLabel={bestSavingsLabel}
                  rungs={ladderRungs}
                />
              </div>
            </section>
          )}

          {/* ═══════════ PRODUCT INDEX — chooser + at-a-glance, merged & asymmetric ═══════════ */}
          <section id="index" className="tone-panel py-20 sm:py-24 scroll-mt-24">
            <div className="rail grid gap-10 lg:grid-cols-[0.72fr_1.28fr] lg:items-start">
              <Reveal>
                <span className="eyebrow"><IconApps size={14} /> Where to start</span>
                <h2 className="mt-4 text-4xl font-bold leading-[1.05] tracking-tight text-white sm:text-5xl text-balance">
                  Five products.<br /><span className="grad-text">One account.</span>
                </h2>
                <p className="mt-5 max-w-sm text-[15px] leading-relaxed text-slate-400">
                  Tell us what you're building and jump straight to the real numbers — starting prices below
                  are read live from the same catalogue the checkout charges.
                </p>
              </Reveal>
              <Reveal delay={100}>
                <div className="grid gap-3">
                  {INDEX.map((o) => (
                    <a
                      key={o.name}
                      href={o.href}
                      className="card card-hover group grid grid-cols-[auto_1fr_auto] items-center gap-4 py-4"
                    >
                      <span className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-${o.accent}`}>
                        {o.icon}
                      </span>
                      <span className="min-w-0">
                        <span className="flex items-center gap-2 font-semibold text-white transition-colors group-hover:text-brand-200">
                          {o.name} <IconArrow size={13} className="opacity-0 transition-opacity group-hover:opacity-100" />
                        </span>
                        <span className="mt-0.5 block truncate text-sm text-slate-400">{o.who}</span>
                      </span>
                      <span className="text-right">
                        <span className="block font-bold text-white">{o.from}</span>
                        <span className="mt-0.5 block text-[11px] text-slate-500">{o.billing}</span>
                      </span>
                    </a>
                  ))}
                </div>
                <p className="mt-4 text-sm text-slate-500">
                  *Domain prices are indicative per year — search a name for the exact live figure.
                </p>
              </Reveal>
            </div>
          </section>

          {/* Sticky product switcher */}
          <PricingNav items={NAV} />

          {/* ═══════════ VPS ═══════════ */}
          <Section size="lg" id="vps" className="scroll-mt-[150px]">
            <div className="flex flex-wrap items-end justify-between gap-6">
              <div className="max-w-xl">
                <span className="eyebrow"><IconTerminal size={14} /> Cloud VPS</span>
                <h2 className="mt-4 text-4xl font-bold tracking-tight text-white sm:text-5xl text-balance">Full-control virtual servers</h2>
                <p className="mt-4 text-lg leading-relaxed text-slate-400">
                  Root access, a dedicated IPv4, NVMe storage and DDoS protection on every plan — you only
                  choose how much horsepower you need. Billed monthly, resize anytime.
                </p>
              </div>
              {vpsFrom != null && (
                <div className="rounded-2xl border border-brand-500/20 bg-brand-500/[0.06] px-6 py-4">
                  <p className="text-[11px] font-semibold uppercase tracking-wider text-brand-200">Starts at</p>
                  <p className="mt-1 text-3xl font-black text-white">{money(vpsFrom)}<span className="text-base font-normal text-slate-400">/mo</span></p>
                </div>
              )}
            </div>

            {vpsPlans.length === 0 ? (
              <p className="mt-10 text-slate-400">Plans are being provisioned — check back shortly.</p>
            ) : (
              <Reveal className="mt-10">
                <div className="card overflow-x-auto p-0">
                  <table className="table-shell min-w-[680px]">
                    <thead>
                      <tr>
                        <th>Plan</th>
                        {vpsPlans.map((p, i) => {
                          const popular = vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2);
                          const best = vpsPlans.length >= 3 && i === vpsPlans.length - 1;
                          return (
                            <th key={p.id} className="text-center">
                              <div className="flex flex-col items-center gap-1">
                                {popular ? (
                                  <span className="rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white">Most popular</span>
                                ) : best ? (
                                  <span className="rounded-full border border-accent-cyan/40 bg-accent-cyan/10 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-accent-cyan">Best value</span>
                                ) : (
                                  <span className="h-[16px]" />
                                )}
                                <span>{p.name}</span>
                              </div>
                              <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}/mo</div>
                            </th>
                          );
                        })}
                      </tr>
                    </thead>
                    <tbody>
                      <tr>
                        <td className="font-medium text-slate-300">vCPU</td>
                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.cpuCores}</td>)}
                      </tr>
                      <tr>
                        <td className="font-medium text-slate-300">RAM</td>
                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{gb(p.ramMB)}</td>)}
                      </tr>
                      <tr>
                        <td className="font-medium text-slate-300">Storage</td>
                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.diskGB} GB</td>)}
                      </tr>
                      <tr>
                        <td className="font-medium text-slate-300">Bandwidth</td>
                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.bandwidthTB} TB</td>)}
                      </tr>
                      {VPS_FEATURES.map((feat) => (
                        <tr key={feat}>
                          <td className="font-medium text-slate-300">{feat}</td>
                          {vpsPlans.map((p) => (
                            <td key={p.id} className="text-center">
                              <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={13} /></span>
                            </td>
                          ))}
                        </tr>
                      ))}
                      <tr>
                        <td />
                        {vpsPlans.map((p) => (
                          <td key={p.id} className="text-center">
                            <Link href="/register" className="btn-secondary inline-flex px-4 py-2 text-xs">Deploy</Link>
                          </td>
                        ))}
                      </tr>
                    </tbody>
                  </table>
                </div>
                <p className="mt-4 text-sm text-slate-500">
                  Billed monthly from your wallet — the price shown is the price you pay, at sign-up and at renewal.{" "}
                  {annualPct > 0 && (
                    <span className="text-accent-cyan">Prefer to pay yearly? Save {annualPct}% with annual billing — see the commitment ladder above.{" "}</span>
                  )}
                  <Link href="/vps" className="text-brand-300 hover:underline">Explore VPS</Link>
                </p>
              </Reveal>
            )}
          </Section>

          {/* ═══════════ GAME SERVERS — intro paired with a live control-panel screen ═══════════ */}
          <Section tone="panel" size="lg" id="game-servers" className="scroll-mt-[150px]">
            <div className="grid items-center gap-10 lg:grid-cols-[1fr_1fr]">
              <Reveal>
                <span className="eyebrow"><IconGame size={14} /> Game Servers</span>
                <h2 className="mt-4 text-4xl font-bold tracking-tight text-white sm:text-5xl text-balance">Per-game plans, honestly priced</h2>
                <p className="mt-4 text-lg leading-relaxed text-slate-400">
                  Six popular titles get dedicated per-game plans tuned to how they run — anything else
                  deploys on a Nxeon VPS. Prices are per game, per month, all-in.
                </p>
                {gameMin && (
                  <p className="mt-6 inline-flex items-baseline gap-2 rounded-xl border border-emerald-500/20 bg-emerald-500/[0.06] px-4 py-2.5 text-sm">
                    <span className="text-slate-400">From</span>
                    <span className="text-xl font-bold text-emerald-300">{money(gameMin.priceCents)}</span>
                    <span className="text-slate-500">/mo</span>
                  </p>
                )}
              </Reveal>
              <Reveal delay={120}><GameControlPanel /></Reveal>
            </div>

            {games.length === 0 ? (
              <p className="mt-12 text-slate-400">Game plans are being configured — check back shortly.</p>
            ) : (
              <div className="mt-14 space-y-12">
                {games.map((fam) => {
                  const meta = GAME_META[fam] ?? { name: fam, tag: "" };
                  const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
                  const from = Math.min(...tiers.map((t) => t.priceCents));
                  return (
                    <Reveal key={fam}>
                      <div className="flex flex-wrap items-baseline justify-between gap-2">
                        <div>
                          <h3 className="text-xl font-bold text-white">{meta.name}</h3>
                          {meta.tag && <p className="text-sm text-slate-400">{meta.tag}</p>}
                        </div>
                        <span className="text-sm text-slate-400">from <span className="font-semibold text-emerald-300">{money(from)}/mo</span></span>
                      </div>
                      <div className="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                        {tiers.map((t) => (
                          <div key={t.id} className={`card flex h-full flex-col ${t.featured ? "border-emerald-400/50 ring-1 ring-emerald-400/30" : ""}`}>
                            <div className="flex items-center justify-between gap-2">
