                  <div key={f.label} className="card flex flex-col items-center gap-3 text-center">
                    <span className="flex h-11 w-11 items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
                      {f.icon}
                    </span>
                    <span className="text-sm font-semibold text-white">{f.label}</span>
                  </div>
                ))}
              </div>
            </Reveal>
          </Section>

          {/* ═══════════ FAQ — asymmetric: sticky heading + questions ═══════════ */}
          <Section tone="panel" size="md">
            <div className="grid gap-10 lg:grid-cols-[0.6fr_1.4fr]">
              <div className="lg:sticky lg:top-28 lg:self-start">
